-- VM
local C={}
C[1]=""
C[2]=""
C[3]=""
C[4]=""
C[5]=""
local K={}
K[1]={99,177,28,120}
K[2]={175,96,251,247}
K[3]={137,36,251,15}
K[4]={144,138,139,130}
K[5]={118,86,51,61}
local P={19,16,20,18,17}
local PK=16
local M=100003
local N=5
local XT={}
for i=0,255 do
  XT[i]={}
  for j=0,255 do
    local r,p=0,1
    local x,y=i,j
    while x>0 or y>0 do
      local xa,ya=x%2,y%2
      if xa~=ya then r=r+p end
      x=(x-xa)/2 y=(y-ya)/2 p=p*2
    end
    XT[i][j]=r
  end
end
local HEX={}
for i=0,255 do HEX[string.format('%02x',i)]=i end
local function D(h,k)
  local n=#h/2
  local o={}
  for i=1,n do
    local v=HEX[h:sub(i*2-1,i*2)]
    local kk=k[(i-1)%4+1]
    o[i]=string.char(XT[v][kk])
  end
  return table.concat(o)
end
local B={}
for i=1,N do
  local src=(P[i]%M)-PK
  if src<0 then src=src+M end
  B[src+1]=D(C[src+1],K[src+1])
end
local L1=table.concat(B)
local f,e=loadstring(L1)
if not f then return end
return f()
